package com.bank.loanopt.service;

import java.util.logging.Logger;

// 0/1 Knapsack by top-down memoized recursion over (index, remaining budget).
public class LoanPortfolioOptimizer {
    private static final Logger log = Logger.getLogger(LoanPortfolioOptimizer.class.getName());

    private int[] capital;
    private int[] profit;
    private int[][] memo;

    public long maxProfit(int[] capitalNeeded, int[] loanProfit, int budget) {
        this.capital = capitalNeeded;
        this.profit = loanProfit;
        int n = capitalNeeded.length;
        this.memo = new int[n][budget + 1];
        for (int[] row : memo) java.util.Arrays.fill(row, -1); // -1 means not computed
        long result = best(0, budget);
        log.info(() -> "Maximum portfolio profit within budget = " + result);
        return result;
    }

    private int best(int i, int cap) {
        if (i == capital.length) return 0;                 // no items left
        if (memo[i][cap] != -1) return memo[i][cap];       // reuse cached subproblem
        int exclude = best(i + 1, cap);                    // skip this loan
        int include = 0;
        if (capital[i] <= cap) {                           // fund only if it fits
            include = profit[i] + best(i + 1, cap - capital[i]);
        }
        return memo[i][cap] = Math.max(exclude, include);  // keep the better choice
    }
}
