package com.bank.loanopt;

import com.bank.loanopt.service.LoanPortfolioOptimizer;
import java.util.logging.Logger;

public class LoanPortfolioApplication {
    private static final Logger log = Logger.getLogger(LoanPortfolioApplication.class.getName());

    public static void main(String[] args) {
        LoanPortfolioOptimizer optimizer = new LoanPortfolioOptimizer();
        int[] capital = {1, 3, 4, 5};                      // capital each loan needs
        int[] profit = {1, 4, 5, 7};                       // projected profit
        long best = optimizer.maxProfit(capital, profit, 7); // budget = 7 units
        log.info(() -> "Final selected profit = " + best);
    }
}
